command:
python3 - <<'PY'
path='mux.go'
s=open(path).read()
old='''func (s *MuxSession) handleSYN(sid uint32, priority uint8, payload []byte) {
	if sid == 0 {
		return
	}
	s.mu.Lock()
	st, ok := s.streams[sid]
'''
new='''func (s *MuxSession) handleSYN(sid uint32, priority uint8, payload []byte) {
	if sid == 0 {
		return
	}
	s.mu.Lock()
	if s.isClosed() {
		s.mu.Unlock()
		return
	}
	st, ok := s.streams[sid]
'''
assert old in s
s=s.replace(old,new)
open(path,'w').write(s)
PY
gofmt -w mux.go && go build ./... && timeout 25 go test -race -run 'TestMux' -count=1 -timeout 20s . 2>&1 | tail -10; echo "EXIT: $?"
